  let hasIndoor  = false;

  for (const r of rows) {
    if (!r) continue;
    const m = String(r.mode ?? '').trim().toLowerCase();
    if (m === 'outdoor') hasOutdoor = true;
    if (m === 'indoor')  hasIndoor  = true;
  }

