// MQTT TS poll -> UI
function fmt(ts){
  if (!ts) return 'n/a';
  try {
    const d = new Date(ts);
    return d.toISOString().replace('T',' ').replace('Z','');
  } catch(e) { return String(ts); }
}

const out1 = {payload: fmt(flow.get('bed1_last_mqtt_ts'))};
const out2 = {payload: fmt(flow.get('bed2_last_mqtt_ts'))};

node.send([out1, out2]);
return null;

// MQTT TS ANY: aggiorna "Ultimo MQTT" SOLO del bed del messaggio
function pad(n){ return String(n).padStart(2,'0'); }
function fmtLocal(d){
  return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())+' '+pad(d.getHours())+':'+pad(d.getMinutes())+':'+pad(d.getSeconds());
}
function bedFrom(msg){
  const t = String(msg.topic||'').toLowerCase();
  // caso tipico: serra/telemetry/bed2
  const parts = t.split('/');
  for (const p of parts){
    if (p === 'bed1' || p === 'bed2') return p;
    // gestisce anche "bed 1" (solo se qualcuno lo manda così)
    if (p.replace(/\s+/g,'') === 'bed1') return 'bed1';
    if (p.replace(/\s+/g,'') === 'bed2') return 'bed2';
  }
  // fallback da payload
  try{
    const p = msg.payload;
    if (p && typeof p === 'object'){
      const z = String(p.zone || p.bed || '').toLowerCase().replace(/\s+/g,'');
      if (z === 'bed1' || z === 'bed2') return z;
    }
  }catch(e){}
  return '';
}

try{
  const bed = bedFrom(msg);
  if (!bed) return [null,null];
  const now = new Date();
  const out = { payload: fmtLocal(now), topic: 'last_mqtt/'+bed };
  if (bed === 'bed1') return [out, null];
  if (bed === 'bed2') return [null, out];
  return [null,null];
}catch(e){
  node.warn('MQTT TS ANY ERR: '+e);
  return [null,null];
}

// salva dir in flow (up/down) - NO MQTT
