  if (v === true || v === 1) return 1;
  if (v === false || v === 0) return 0;
  const s = String(v ?? '').trim().toLowerCase();
  if (s === '1' || s === 'true' || s === 'on') return 1;
  if (s === '0' || s === 'false' || s === 'off') return 0;
  return null;
}
