    if (p === 'bed1' || p === 'bed2') return p;
    const px = p.replace(/\s+/g,'');
    if (px === 'bed1' || px === 'bed2') return px;
  }
  try{
    if (payload && typeof payload === 'object'){
      const z = String(payload.zone || payload.bed || '').toLowerCase().replace(/\s+/g,'');
      if (z === 'bed1' || z === 'bed2') return z;
    }
  }catch(e){}
  return '';
}

try{
  const topic = String(msg.topic||'');
  const t = topic.toLowerCase();
  const p = msg.payload;

  const bed = bedFrom(topic, p);
  if (!bed) return null;

  let led = null;
  let pump = null;

  // pattern ACK per singolo relay: .../relay/led o .../relay/pump
  if (t.includes('/relay/led')) {
    led = (p && typeof p === 'object' && ('on' in p)) ? as01(p.on) : as01(p);
  }
  if (t.includes('/relay/pump')) {
    pump = (p && typeof p === 'object' && ('on' in p)) ? as01(p.on) : as01(p);
  }

  // pattern ACK “stato completo” nel payload
  if (p && typeof p === 'object'){
    if (led is null && ('relay_led' in p)) led = as01(p.relay_led);
    if (pump is null && ('relay_pump' in p)) pump = as01(p.relay_pump);
    if (led is null && ('led' in p)) led = as01(p.led);
    if (pump is null && ('pump' in p)) pump = as01(p.pump);
  }

  const sets = [];
  if (led !== null) sets.push('relay_led='+led);
  if (pump !== null) sets.push('relay_pump='+pump);
  if (!sets.length) return null;

  msg.topic = 'ack2db';
  msg.payload = "UPDATE telemetry_last SET "+sets.join(', ')+", ts=datetime('now','localtime') WHERE zone='"+bed+"';";
  return msg;
}catch(e){
  node.warn('ACK→DB ERR: '+e);
  return null;
}
